/* ===== casino.js ===== */
/* games/casino.js  |  PF v1.4.3 | XP CASINO: wagers, lottery, coin flip, crash, roulette.
   LAYERING: a game silo like campaign.js. Reads via JSONP (self-contained api()),
   writes via CORS POST — wagers use {type:"wager",w_action:...}, everything else
   uses {type:"gamble",g_action:...}. It never reaches into another silo's internals.
   XP has no cash value — social gambling for movement engagement.
   KILL: ?pf_off=casino  or  localStorage pf_disabled_v1='["casino"]' */
(function () {
  'use strict';
  var PF = window.PF;
  if (PF.skip("casino")) { return; }
  PF.holder().insertAdjacentHTML('beforeend', `<template id="pf-ov-casino">
<div class="fe-block pf-override-block" id="pf-casino">
<h2>XP Casino</h2>
<div class="c-tag">Wager your XP. Winner takes the glory — and the pot.</div>
<div id="xCasino"><div class="c-load">Rolling the dice&hellip;</div></div>
</div>
<script>
(function(){
var BACKEND=window.PF_BACKEND_URL;
function esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
function ident(){ var cs="",dev=""; try{ cs=window.PFCallsign?window.PFCallsign():""; }catch(e){} try{ dev=window.PFDeviceId?window.PFDeviceId():""; }catch(e){} return {callsign:cs,device:dev}; }
function toast(m){ try{ if(window.PF&&PF.toast){ PF.toast(m); return; } }catch(e){}
  try{ var t=document.createElement("div"); t.textContent=m;
  t.style.cssText="position:fixed;left:50%;top:16%;transform:translateX(-50%);background:#c1121f;color:#fff;font:bold 15px monospace;padding:12px 22px;border:2px solid #fff;z-index:99999";
  document.body.appendChild(t); setTimeout(function(){ t.remove(); },2800); }catch(e2){} }
/* JSONP GET for reads. */
function api(action,params,cb){
  if(!BACKEND){ cb(null); return; }
  var fn="pfCsCb"+Math.floor(Math.random()*1e9);
  var s=document.createElement("script"), done=false;
  function finish(j){ if(done)return; done=true; try{delete window[fn];}catch(e){}
    if(s.parentNode)s.parentNode.removeChild(s); cb(j); }
  window[fn]=function(j){ finish(j); };
  s.onerror=function(){ finish(null); };
  var q="?action="+encodeURIComponent(action);
  for(var k in params){ if(params[k]!=null&&params[k]!=="") q+="&"+encodeURIComponent(k)+"="+encodeURIComponent(params[k]); }
  q+="&callback="+fn; s.src=BACKEND+q; document.head.appendChild(s);
  setTimeout(function(){ finish(null); },12000);
}
/* CORS POST for writes — real fetch, backend verdict parsed. */
function postW(wAction,params,cb){
  var body=Object.assign({type:"wager",w_action:wAction},params);
  if(window.PF&&PF.authPost){ PF.authPost(BACKEND,body,cb); return; }
  var bodyStr=JSON.stringify(body);
  function done(j){ try{ cb(j||{ok:false,err:"Network error."}); }catch(e){} }
  try{
    fetch(BACKEND,{method:"POST",headers:{"Content-Type":"application/json"},body:bodyStr})
      .then(function(r){ return r.json(); })
      .then(function(j){ done(j); })
      .catch(function(){ done(null); });
  }catch(e){ done(null); }
}
function postG(gAction,params,cb){
  var body=Object.assign({type:"gamble",g_action:gAction},params);
  if(window.PF&&PF.authPost){ PF.authPost(BACKEND,body,cb); return; }
  var bodyStr=JSON.stringify(body);
  function done(j){ try{ cb(j||{ok:false,err:"Network error."}); }catch(e){} }
  try{
    fetch(BACKEND,{method:"POST",headers:{"Content-Type":"application/json"},body:bodyStr})
      .then(function(r){ return r.json(); })
      .then(function(j){ done(j); })
      .catch(function(){ done(null); });
  }catch(e){ done(null); }
}
var W=null, L=null, F=null, C=null;
var crashTimer=null;
function fmtTime(ms){
  if(!ms) return "";
  var s=Math.max(0,Math.floor((ms-Date.now())/1000));
  var d=Math.floor(s/86400), h=Math.floor(s%86400/3600), m=Math.floor(s%3600/60);
  return (d>0?d+"d ":"")+(h>0?h+"h ":"")+m+"m";
}
function load(){
  var done=false, n=0;
  function fin(){ if(done)return; done=true; render(); }
  function one(){ n++; if(n>=4) fin(); }
  setTimeout(fin,15000);
  api("wager_list",{},function(j){ W=j; one(); });
  api("lottery_status",{},function(j){ L=j; one(); });
  api("flip_open",{},function(j){ F=j; one(); });
  api("crash_status",{},function(j){ C=j; one(); });
}
/* ============ WAGERS ============ */
function renderWagers(id){
  var ws=(W&&W.wagers)||[];
  var h='<div class="x-pane"><h4>Wagers</h4><div class="x-note">Bet XP on battles, races, and challenges. Winners split the pool.</div>';
  if(!ws.length){ h+='<div class="x-note">No open wagers right now. Check back soon.</div>'; }
  for(var i=0;i<ws.length;i++){
    var w=ws[i];
    if(w.resolved){
      h+='<div class="cs-wager"><div class="cs-wdesc">'+esc(w.description)+'</div>'
        +'<div class="cs-wres">RESOLVED — winner: '+esc(w.outcome)+'</div></div>';
      continue;
    }
    h+='<div class="cs-wager"><div class="cs-wdesc">'+esc(w.description)+'</div>'
      +'<div class="x-note">'+esc(w.kind)+' &bull; pot: '+(Number(w.total_pool)||0)+' XP &bull; closes '+fmtTime(w.closes_at)+'</div>';
    var sides=w.sides||[];
    for(var s=0;s<sides.length;s++){
      var sd=sides[s], pool=Number(w.total_pool)||0, sb=Number(sd.total_bet)||0;
      var odds=sb>0?("pays "+(pool/sb).toFixed(1)+"x"):"no bets yet";
      h+='<div class="cs-side"><span class="cs-sname">'+esc(sd.side)+'</span>'
        +' <span class="cs-odds">'+esc(odds)+' ('+sb+' XP)</span>'
        +'<button class="c-btn cs-betbtn" data-wid="'+esc(w.id)+'" data-side="'+esc(sd.side)+'">BET</button></div>';
    }
    h+='<div class="cs-betrow"><input class="c-input cs-amt" id="csAmt_'+esc(w.id)+'" type="number" min="1" placeholder="XP amount" style="width:120px">'
      +'<span class="x-note">Enter amount, then hit BET on your side.</span></div></div>';
  }
  h+='</div>';
  return h;
}
/* ============ LOTTERY ============ */
function renderLottery(id){
  var r=(L&&L.round)||null;
  var h='<div class="x-pane"><h4>Lottery</h4><div class="x-note">10 XP per ticket. Winner takes the whole pot. Drawn weekly.</div>';
  if(!r){ h+='<div class="x-note">Lottery loading&hellip;</div></div>'; return h; }
  h+='<div class="cs-pot">'+(Number(r.pot)||0)+' XP POT</div>'
    +'<div class="x-note">Draws in '+fmtTime(r.ends_at)+' &bull; '+(Number(r.total_tickets)||0)+' tickets in play &bull; you hold '+(Number(r.my_tickets)||0)+'</div>'
    +'<div class="cs-btnrow"><button class="c-btn" data-tk="1">BUY 1</button>'
    +'<button class="c-btn" data-tk="5">BUY 5</button>'
    +'<button class="c-btn" data-tk="10">BUY 10</button></div>'
    +'<div class="c-err" id="csLotErr"></div></div>';
  return h;
}
/* ============ COIN FLIP ============ */
function renderFlip(id){
  var fl=(F&&F.flips)||[];
  var h='<div class="x-pane"><h4>Coin Flip</h4><div class="x-note">Heads or tails. Winner takes double. 5% rake feeds the lottery.</div>'
    +'<div class="cs-betrow"><input class="c-input" id="csFlipAmt" type="number" min="1" placeholder="XP amount" style="width:110px">'
    +'<select class="c-input" id="csFlipSide" style="width:110px"><option value="heads">HEADS</option><option value="tails">TAILS</option></select>'
    +'<button class="c-btn" id="csFlipCreate">CREATE FLIP</button></div>'
    +'<div class="c-err" id="csFlipErr"></div>';
  h+='<h4 style="margin-top:8px">Open flips</h4>';
  if(!fl.length){ h+='<div class="x-note">No open flips. Create one and dare someone to take it.</div>'; }
  for(var i=0;i<fl.length;i++){
    var f=fl[i];
    if(String(f.creator||"").toUpperCase()===String(id.callsign||"").toUpperCase()) continue;
    h+='<div class="cs-flip"><span>'+esc(f.creator)+' bets '+(Number(f.amount)||0)+' XP on '+esc(f.side).toUpperCase()+'</span>'
      +'<button class="c-btn cs-takebtn" data-fid="'+esc(f.id)+'">TAKE IT</button></div>';
  }
  h+='</div>';
  return h;
}
/* ============ CRASH ============ */
function renderCrash(id){
  var mult=(C&&C.multiplier!=null)?Number(C.multiplier):1.0;
  var crashed=!!(C&&C.crashed);
  var bets=(C&&C.bets)||[];
  var myBet=null;
  for(var i=0;i<bets.length;i++){ if(String(bets[i].bettor||"").toUpperCase()===String(id.callsign||"").toUpperCase()){ myBet=bets[i]; break; } }
  var h='<div class="x-pane"><h4>Crash</h4><div class="x-note">Multiplier climbs. Cash out before it crashes — or lose it all.</div>';
  h+='<div class="cs-crashmult'+(crashed?' cs-crashed':'')+'" id="csMult">'+mult.toFixed(2)+'x</div>';
  if(crashed){ h+='<div class="cs-crashmsg">CRASHED. Next round starting.</div>'; }
  else if(myBet&&!myBet.cashed_out){
    h+='<div class="x-note">You\'re in for '+(Number(myBet.amount)||0)+' XP at '+mult.toFixed(2)+'x = '+Math.floor((Number(myBet.amount)||0)*mult)+' XP</div>'
      +'<button class="c-btn cs-cashout" id="csCashout">CASH OUT</button>';
  } else {
    h+='<div class="cs-betrow"><input class="c-input" id="csCrashAmt" type="number" min="1" placeholder="XP amount" style="width:120px">'
      +'<button class="c-btn" id="csCrashBet">PLACE BET</button></div>';
  }
  h+='<div class="x-note">'+bets.length+' in this round</div><div class="c-err" id="csCrashErr"></div></div>';
  return h;
}
/* ============ ROULETTE ============ */
function renderRoulette(id){
  var h='<div class="x-pane"><h4>Roulette</h4><div class="x-note">Red/black pays 2x. Single number pays 36x. 5% of losses feed the lottery.</div>'
    +'<div class="cs-betrow"><select class="c-input" id="csRouType" style="width:120px">'
    +'<option value="red">RED</option><option value="black">BLACK</option><option value="number">NUMBER</option></select>'
    +'<input class="c-input" id="csRouVal" type="number" min="0" max="36" placeholder="0-36" style="width:80px">'
    +'<input class="c-input" id="csRouAmt" type="number" min="1" placeholder="XP" style="width:90px">'
    +'<button class="c-btn" id="csSpin">SPIN</button></div>'
    +'<div class="cs-roures" id="csRouRes"></div><div class="c-err" id="csRouErr"></div></div>';
  return h;
}
function render(){
  var el=document.getElementById("xCasino"); if(!el) return;
  var id=ident();
  var h='<div class="cs-frame">THE HOUSE ALWAYS WINS? NOT WHEN THE HOUSE IS US.</div>';
  if(!id.callsign){
    h+='<div class="c-gate">Casino runs on callsigns. Claim yours in Enlistment Ranks, then come back and play.</div>';
    el.innerHTML=h; return;
  }
  h+=renderWagers(id)+renderLottery(id)+renderFlip(id)+renderCrash(id)+renderRoulette(id);
  h+='<div style="margin-top:10px"><button class="c-btn" id="csRetry">Refresh</button></div>';
  el.innerHTML=h;
  wire(id);
  startCrashPoll();
}
function wire(id){
  var el=document.getElementById("xCasino"); if(!el) return;
  /* --- wager bets --- */
  var bb=el.querySelectorAll("button.cs-betbtn");
  for(var i=0;i<bb.length;i++){
    (function(btn){
      btn.onclick=function(){
        var wid=btn.getAttribute("data-wid"), side=btn.getAttribute("data-side");
        var amtEl=document.getElementById("csAmt_"+wid);
        var amt=amtEl?parseInt(amtEl.value,10):0;
        if(!amt||amt<1){ toast("Enter an XP amount first."); return; }
        btn.disabled=true;
        postW("wager_place",{callsign:id.callsign,wager_id:wid,side:side,amount:amt},function(j){
          btn.disabled=false;
          if(!j||!j.ok){ toast((j&&j.err)||"Bet failed."); return; }
          toast("BET PLACED: "+amt+" XP on "+side+".");
          load();
        });
      };
    })(bb[i]);
  }
  /* --- lottery --- */
  var lb=el.querySelectorAll("button[data-tk]");
  for(var l=0;l<lb.length;l++){
    (function(btn){
      btn.onclick=function(){
        var tk=parseInt(btn.getAttribute("data-tk"),10);
        btn.disabled=true;
        postG("lottery_buy",{callsign:id.callsign,tickets:tk},function(j){
          btn.disabled=false;
          var e=document.getElementById("csLotErr");
          if(!j||!j.ok){ if(e) e.textContent=(j&&j.err)||"Buy failed."; return; }
          toast(tk+" ticket"+(tk>1?"s":"")+" in the draw. Good luck.");
          load();
        });
      };
    })(lb[l]);
  }
  /* --- coin flip create --- */
  var fc=document.getElementById("csFlipCreate");
  if(fc) fc.onclick=function(){
    var amt=parseInt((document.getElementById("csFlipAmt")||{}).value,10);
    var side=(document.getElementById("csFlipSide")||{}).value||"heads";
    var e=document.getElementById("csFlipErr");
    if(!amt||amt<1){ if(e) e.textContent="Enter an XP amount."; return; }
    fc.disabled=true;
    postG("flip_create",{callsign:id.callsign,amount:amt,side:side},function(j){
      fc.disabled=false;
      if(!j||!j.ok){ if(e) e.textContent=(j&&j.err)||"Create failed."; return; }
      toast("FLIP OPEN: "+amt+" XP on "+side.toUpperCase()+".");
      load();
    });
  };
  /* --- coin flip take --- */
  var tb=el.querySelectorAll("button.cs-takebtn");
  for(var t=0;t<tb.length;t++){
    (function(btn){
      btn.onclick=function(){
        btn.disabled=true;
        postG("flip_join",{callsign:id.callsign,flip_id:btn.getAttribute("data-fid")},function(j){
          btn.disabled=false;
          if(!j||!j.ok){ toast((j&&j.err)||"Join failed."); return; }
          toast(j.winner?(String(j.winner).toUpperCase()===String(id.callsign).toUpperCase()?"YOU WIN THE FLIP!":"Flip lost. Winner: "+j.winner):"Flip resolved.");
          load();
        });
      };
    })(tb[t]);
  }
  /* --- crash bet --- */
  var cb=document.getElementById("csCrashBet");
  if(cb) cb.onclick=function(){
    var amt=parseInt((document.getElementById("csCrashAmt")||{}).value,10);
    var e=document.getElementById("csCrashErr");
    if(!amt||amt<1){ if(e) e.textContent="Enter an XP amount."; return; }
    cb.disabled=true;
    postG("crash_bet",{callsign:id.callsign,amount:amt},function(j){
      cb.disabled=false;
      if(!j||!j.ok){ if(e) e.textContent=(j&&j.err)||"Bet failed."; return; }
      toast("IN FOR "+amt+" XP. Cash out before it crashes.");
      load();
    });
  };
  /* --- crash cashout --- */
  var co=document.getElementById("csCashout");
  if(co) co.onclick=function(){
    co.disabled=true; co.textContent="CASHING OUT...";
    postG("crash_cashout",{callsign:id.callsign},function(j){
      if(!j||!j.ok){ toast((j&&j.err)||"Cashout failed."); load(); return; }
      toast("CASHED OUT: +"+(j.payout||0)+" XP!");
      load();
    });
  };
  /* --- roulette --- */
  var sp=document.getElementById("csSpin");
  if(sp) sp.onclick=function(){
    var bt=(document.getElementById("csRouType")||{}).value||"red";
    var bv=parseInt((document.getElementById("csRouVal")||{}).value,10);
    var amt=parseInt((document.getElementById("csRouAmt")||{}).value,10);
    var e=document.getElementById("csRouErr"), r=document.getElementById("csRouRes");
    if(!amt||amt<1){ if(e) e.textContent="Enter an XP amount."; return; }
    if(bt==="number"&&(isNaN(bv)||bv<0||bv>36)){ if(e) e.textContent="Pick a number 0-36."; return; }
    sp.disabled=true; sp.textContent="SPINNING...";
    if(e) e.textContent="";
    postG("roulette_spin",{callsign:id.callsign,bet_type:bt,bet_value:bt==="number"?bv:"",amount:amt},function(j){
      sp.disabled=false; sp.textContent="SPIN";
      if(!j||!j.ok){ if(e) e.textContent=(j&&j.err)||"Spin failed."; return; }
      var res=j.result!=null?j.result:"?";
      var pay=Number(j.payout)||0;
      if(r) r.innerHTML='<div class="cs-rounum">'+esc(res)+'</div><div class="'+(pay>0?"cs-win":"cs-lose")+'">'
        +(pay>0?("WON +"+pay+" XP"):("LOST "+amt+" XP"))+'</div>';
      load();
    });
  };
  /* --- refresh --- */
  var rb=document.getElementById("csRetry");
  if(rb) rb.onclick=function(){ W=L=F=C=null; var el2=document.getElementById("xCasino"); if(el2) el2.innerHTML='<div class="c-load">Rolling the dice&hellip;</div>'; load(); };
}
function startCrashPoll(){
  if(crashTimer) return;
  crashTimer=setInterval(function(){
    var el=document.getElementById("csMult"); if(!el) return;
    api("crash_status",{},function(j){
      if(!j||!j.ok) return;
      C=j;
      var m=document.getElementById("csMult");
      if(m){ m.textContent=(Number(j.multiplier)||1).toFixed(2)+"x";
        if(j.crashed){ m.className="cs-crashmult cs-crashed"; }
      }
    });
  },2000);
}
load();
setInterval(function(){ load(); },120000);
})();
</scr`+`ipt>
</div>
</template>`);
})();

;

/* ===== vault.js ===== */
/* games/vault.js  |  PF v1.4.3 | ADMIN VAULT: Shane's financial control panel.
   Admin-only UI for the XP financial system — lottery, wagers, subs, causes,
   prizes, events, drops, alerts. Public reads via JSONP, admin reads via fetch
   GET with X-Admin-Secret, admin writes via CORS POST with X-Admin-Secret.
   Secret is prompted once per session and kept in sessionStorage only.
   KILL: ?pf_off=vault  or  localStorage pf_disabled_v1='["vault"]' */
(function () {
  'use strict';
  var PF = window.PF;
  if (PF.skip("vault")) { return; }
  PF.holder().insertAdjacentHTML('beforeend', `<template id="pf-ov-vault">
<div class="fe-block pf-override-block" id="pf-vault">
<h2>Admin Vault</h2>
<div class="c-tag">Financial control room. Restricted access.</div>
<div id="xVault"><div class="c-load">Checking credentials&hellip;</div></div>
</div>
<script>
(function(){
var BACKEND=window.PF_BACKEND_URL;
var SECRET_KEY="pf_admin_secret";
function esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
function toast(m){ try{ if(window.PF&&PF.toast){ PF.toast(m); return; } }catch(e){}
  try{ var t=document.createElement("div"); t.textContent=m;
  t.style.cssText="position:fixed;left:50%;top:16%;transform:translateX(-50%);background:#c1121f;color:#fff;font:bold 15px monospace;padding:12px 22px;border:2px solid #fff;z-index:99999";
  document.body.appendChild(t); setTimeout(function(){ t.remove(); },3200); }catch(e2){} }
function getSecret(){ try{ return sessionStorage.getItem(SECRET_KEY)||""; }catch(e){ return ""; } }
function setSecret(s){ try{ sessionStorage.setItem(SECRET_KEY,s); }catch(e){} }
function clearSecret(){ try{ sessionStorage.removeItem(SECRET_KEY); }catch(e){} }
function api(action,params,cb){
  if(!BACKEND){ cb(null); return; }
  var fn="pfVlCb"+Math.floor(Math.random()*1e9);
  var s=document.createElement("script"), done=false;
  function finish(j){ if(done)return; done=true; try{delete window[fn];}catch(e){}
    if(s.parentNode)s.parentNode.removeChild(s); cb(j); }
  window[fn]=function(j){ finish(j); };
  s.onerror=function(){ finish(null); };
  var q="?action="+encodeURIComponent(action);
  for(var k in params){ if(params[k]!=null&&params[k]!=="") q+="&"+encodeURIComponent(k)+"="+encodeURIComponent(params[k]); }
  q+="&callback="+fn; s.src=BACKEND+q; document.head.appendChild(s);
  setTimeout(function(){ finish(null); },12000);
}
function apiAdmin(action,cb){
  function done(j){ try{ cb(j||{ok:false,err:"Network error."}); }catch(e){} }
  try{
    fetch(BACKEND+"?action="+encodeURIComponent(action),{method:"GET",headers:{"X-Admin-Secret":getSecret()}})
      .then(function(r){ return r.json(); }).then(function(j){ done(j); }).catch(function(){ done(null); });
  }catch(e){ done(null); }
}
function post(type,key,cAction,params,cb){
  var body={type:type}; body[key]=cAction;
  for(var k in params) body[k]=params[k];
  function done(j){ try{ cb(j||{ok:false,err:"Network error."}); }catch(e){} }
  try{
    fetch(BACKEND,{method:"POST",headers:{"Content-Type":"application/json","X-Admin-Secret":getSecret()},body:JSON.stringify(body)})
      .then(function(r){ return r.json(); }).then(function(j){ done(j); }).catch(function(){ done(null); });
  }catch(e){ done(null); }
}
function fmtDate(t){
  try{ var d=new Date(Number(t)); if(isNaN(d.getTime())) return "";
    var mo=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    return mo[d.getMonth()]+" "+d.getDate()+", "+d.getFullYear(); }catch(e){ return ""; }
}
function fmtDur(ms){
  if(ms<=0) return "now";
  var s=Math.floor(ms/1000), d=Math.floor(s/86400); s%=86400;
  var h=Math.floor(s/3600); s%=3600; var m=Math.floor(s/60);
  var out=""; if(d>0)out+=d+"d "; if(h>0||d>0)out+=h+"h "; out+=m+"m";
  return out.trim();
}
function val(id){ var el=document.getElementById(id); return el?String(el.value||"").trim():""; }
function err(id,m){ var el=document.getElementById(id); if(el) el.textContent=m||""; }
var NH=null, LS=null, WL=null, CL=null, EL=null, DL=null, AL=null;
function load(){
  var n=0;
  function one(){ n++; if(n>=7) render(); }
  setTimeout(render,15000);
  apiAdmin("network_health",function(j){ NH=j; one(); });
  api("lottery_status",{callsign:"x"},function(j){ LS=j; one(); });
  api("wager_list",{},function(j){ WL=j; one(); });
  api("cause_list",{},function(j){ CL=j; one(); });
  api("event_list",{},function(j){ EL=j; one(); });
  api("drop_list",{},function(j){ DL=j; one(); });
  api("alert_list",{},function(j){ AL=j; one(); });
}
function renderGate(){
  var el=document.getElementById("xVault"); if(!el) return;
  el.innerHTML='<div class="x-pane"><h4>Restricted area</h4>'
    +'<div class="x-note">The Vault manages the XP financial system. Enter the admin secret to unlock.</div>'
    +'<input id="vlSecret" type="password" class="c-input" placeholder="Admin secret" style="max-width:320px">'
    +'<div style="margin-top:8px"><button class="c-btn" id="vlUnlock">UNLOCK VAULT</button></div>'
    +'<div class="c-err" id="vlGateErr"></div></div>';
  document.getElementById("vlUnlock").onclick=function(){
    var s=val("vlSecret");
    if(!s){ err("vlGateErr","Enter the secret."); return; }
    setSecret(s);
    apiAdmin("network_health",function(j){
      if(j&&j.ok){ toast("Vault unlocked."); load(); }
      else{ clearSecret(); err("vlGateErr",(j&&j.err)||"Invalid secret."); }
    });
  };
}
function render(){
  var el=document.getElementById("xVault"); if(!el) return;
  if(!getSecret()){ renderGate(); return; }
  if(NH&&!NH.ok&&NH.err==="unauthorized"){ clearSecret(); renderGate(); return; }
  var h="";
  h+='<div style="margin-bottom:10px"><button class="c-btn c-btn-dim" id="vlLock">LOCK VAULT</button></div>';
  /* 1. SYSTEM OVERVIEW */
  h+='<div class="x-pane"><h4>System overview</h4>';
  if(NH&&NH.ok){
    h+='<div class="vl-grid">'
      +'<div class="vl-stat"><div class="vl-num">'+Number(NH.total_users||0)+'</div><div class="vl-lab">Soldiers</div></div>'
      +'<div class="vl-stat"><div class="vl-num">'+Number(NH.active_7d||0)+'</div><div class="vl-lab">Active 7d</div></div>'
      +'<div class="vl-stat"><div class="vl-num">'+Number(NH.total_shares||0)+'</div><div class="vl-lab">Total shares</div></div>'
      +'<div class="vl-stat"><div class="vl-num">'+Number(NH.total_content||0)+'</div><div class="vl-lab">Content pieces</div></div>'
      +'</div>';
    var gr=NH.growth||{};
    h+='<div class="x-note">Shares this week: '+(gr.this_week!=null?gr.this_week:"?")+' &bull; last week: '+(gr.last_week!=null?gr.last_week:"?")+'</div>';
    var tc=(NH.top_cells||[]);
    if(tc.length){ h+='<div class="x-note">Top cells: '+tc.slice(0,5).map(function(c){ return esc(c.cell_id||c.id)+" ("+(c.shares||0)+")"; }).join(" &bull; ")+'</div>'; }
  } else {
    h+='<div class="x-note">System overview unavailable ('+esc((NH&&NH.err)||"loading")+').</div>';
  }
  var lr=(LS&&LS.ok&&LS.round)||null;
  if(lr){ h+='<div class="x-note">Lottery pot: <b>'+Number(lr.pot||0)+' XP</b> &bull; '+(lr.total_tickets||0)+' tickets &bull; draw in '+fmtDur(Number(lr.ends_at||0)-Date.now())+'</div>'; }
  h+='</div>';
  /* 2. LOTTERY CONTROL */
  h+='<div class="x-pane"><h4>Lottery control</h4>';
  if(lr){
    h+='<div class="x-note">Round <b>'+esc(lr.id)+'</b> &mdash; pot <b>'+Number(lr.pot||0)+' XP</b>, '+(lr.total_tickets||0)+' tickets, ends '+fmtDate(lr.ends_at)+'</div>'
      +'<button class="c-btn" id="vlDraw">DRAW WINNER</button><div class="c-err" id="vlDrawErr"></div>';
  } else { h+='<div class="x-note">Lottery status loading&hellip;</div>'; }
  h+='</div>';
  /* 3. WAGER MANAGEMENT */
  h+='<div class="x-pane"><h4>Wager management</h4>'
    +'<div class="vl-form">'
    +'<input id="vlWKind" class="c-input" placeholder="Kind: battle | race | challenge" style="max-width:200px">'
    +'<input id="vlWTid" class="c-input" placeholder="Target ID (battle/race/challenge)" style="max-width:260px">'
    +'<input id="vlWDesc" class="c-input" placeholder="Description" style="max-width:320px">'
    +'<input id="vlWSides" class="c-input" placeholder="Sides, comma-separated" style="max-width:320px">'
    +'<input id="vlWClose" class="c-input" type="datetime-local" style="max-width:220px">'
    +'<button class="c-btn" id="vlWCreate">CREATE WAGER</button><div class="c-err" id="vlWErr"></div>'
    +'</div>';
  var ws=(WL&&WL.ok&&WL.wagers)||[];
  if(ws.length){
    h+='<div class="vl-list">';
    for(var i=0;i<ws.length;i++){ var w=ws[i];
      h+='<div class="vl-row"><div><b>'+esc(w.description||w.id)+'</b>'
        +' <span class="x-note">'+esc(w.kind)+' &bull; pool '+Number(w.total_pool||0)+' XP &bull; '+(w.resolved?"RESOLVED: "+esc(w.outcome):"closes "+fmtDate(w.closes_at))+'</span></div>';
      if(!w.resolved){
        h+='<div class="vl-form"><input id="vlWRes_'+esc(w.id)+'" class="c-input" placeholder="Winning side" style="max-width:200px">'
          +'<button class="c-btn" data-wres="'+esc(w.id)+'">RESOLVE</button></div>';
      }
      h+='</div>';
    }
    h+='</div><div class="c-err" id="vlWResErr"></div>';
  } else { h+='<div class="x-note">No wagers yet.</div>'; }
  h+='</div>';
  /* 4. SUBSCRIPTION PROCESSING */
  h+='<div class="x-pane"><h4>Subscription processing</h4>'
    +'<div class="x-note">Run weekly (or on demand) to move due XP from subscribers to creators.</div>'
    +'<button class="c-btn" id="vlSubProc">PROCESS DUE PAYMENTS</button><div class="c-err" id="vlSubErr"></div>'
    +'<div class="x-note" id="vlSubOut"></div></div>';
  /* 5. CAUSE WITHDRAWALS */
  h+='<div class="x-pane"><h4>Cause withdrawals</h4>';
  var cs=(CL&&CL.ok&&CL.pools)||[];
  if(cs.length){
    for(var c=0;c<cs.length;c++){ var p=cs[c];
      h+='<div class="vl-row"><div><b>'+esc(p.name)+'</b> <span class="x-note">'+Number(p.balance||0)+' XP &bull; '+(p.donors||0)+' donors</span>'
        +'<div class="x-note">'+esc(p.description||"")+'</div></div>'
        +'<div class="vl-form"><input id="vlCW_'+esc(p.id)+'" class="c-input" type="number" min="1" placeholder="Amount" style="max-width:140px">'
        +'<input id="vlCWN_'+esc(p.id)+'" class="c-input" placeholder="Disbursement note" style="max-width:240px">'
        +'<button class="c-btn" data-cw="'+esc(p.id)+'">WITHDRAW</button></div></div>';
    }
    h+='<div class="c-err" id="vlCWErr"></div>';
  } else { h+='<div class="x-note">No cause pools.</div>'; }
  h+='</div>';
  /* 6. PRIZE AWARDS */
  h+='<div class="x-pane"><h4>Prize awards</h4>'
    +'<div class="x-note">Award a crowdfunded prize pool to its winner. Pool empties on award.</div>'
    +'<div class="vl-form"><input id="vlPPool" class="c-input" placeholder="Pool ID" style="max-width:200px">'
    +'<input id="vlPWin" class="c-input" placeholder="Winner callsign" style="max-width:200px">'
    +'<button class="c-btn" id="vlPAward">AWARD PRIZE</button><div class="c-err" id="vlPErr"></div></div></div>';
  /* 7. EVENT ATTENDANCE */
  h+='<div class="x-pane"><h4>Event attendance</h4>';
  var ev=(EL&&EL.ok&&EL.events)||[];
  if(ev.length){
    h+='<div class="vl-list">';
    for(var e=0;e<Math.min(ev.length,10);e++){ var ve=ev[e];
      h+='<div class="vl-row"><div><b>'+esc(ve.title)+'</b> <span class="x-note">'+esc(ve.type)+' &bull; '+fmtDate(ve.event_at)+' &bull; '+(ve.rsvp_count||0)+' RSVPs</span></div>'
        +'<div class="vl-form"><input id="vlEA_'+esc(ve.id)+'" class="c-input" placeholder="Callsign" style="max-width:160px">'
        +'<button class="c-btn" data-ea="'+esc(ve.id)+'">CONFIRM ATTENDANCE</button></div></div>';
    }
    h+='</div><div class="c-err" id="vlEAErr"></div>';
  } else { h+='<div class="x-note">No events.</div>'; }
  h+='</div>';
  /* 8. DROPS & ALERTS */
  h+='<div class="x-pane"><h4>Coordinated drops</h4>'
    +'<div class="vl-form"><input id="vlDTitle" class="c-input" placeholder="Drop title" style="max-width:260px">'
    +'<input id="vlDCid" class="c-input" placeholder="Content ID" style="max-width:200px">'
    +'<input id="vlDAt" class="c-input" type="datetime-local" style="max-width:220px">'
    +'<button class="c-btn" id="vlDCreate">CREATE DROP</button><div class="c-err" id="vlDErr"></div></div>';
  var dp=(DL&&DL.ok&&DL.drops)||[];
  if(dp.length){ h+='<div class="x-note">'+dp.length+' scheduled drop(s). Latest: <b>'+esc(dp[0].title)+'</b> &mdash; '+esc(dp[0].commit_count||0)+' committed, drops '+fmtDate(dp[0].drop_at)+'</div>'; }
  h+='</div>';
  h+='<div class="x-pane"><h4>Rapid response alerts</h4>'
    +'<div class="vl-form"><input id="vlAHead" class="c-input" placeholder="Headline" style="max-width:320px">'
    +'<input id="vlACtx" class="c-input" placeholder="Context for creators" style="max-width:320px">'
    +'<input id="vlATpl" class="c-input" placeholder="Template ID (optional)" style="max-width:200px">'
    +'<button class="c-btn" id="vlACreate">CREATE ALERT</button><div class="c-err" id="vlAErr"></div></div>';
  var ax=(AL&&AL.ok&&AL.alerts)||[];
  if(ax.length){ h+='<div class="x-note">'+ax.length+' active alert(s). Latest: <b>'+esc(ax[0].headline)+'</b> &mdash; '+esc(ax[0].response_count||0)+' responses</div>'; }
  h+='</div>';
  el.innerHTML=h;
  wire();
}
function wire(){
  var lock=document.getElementById("vlLock");
  if(lock) lock.onclick=function(){ clearSecret(); NH=null; renderGate(); toast("Vault locked."); };
  var b;
  b=document.getElementById("vlDraw");
  if(b) b.onclick=function(){ b.disabled=true;
    post("gamble","g_action","lottery_draw",{},function(j){
      b.disabled=false;
      if(!j||!j.ok){ err("vlDrawErr",(j&&j.err)||"Draw failed."); return; }
      toast("Winner: "+j.winner+" — "+j.pot+" XP."); LS=null; load();
    }); };
  b=document.getElementById("vlWCreate");
  if(b) b.onclick=function(){ b.disabled=true;
    var sides=val("vlWSides").split(",").map(function(s){ return s.trim(); }).filter(Boolean);
    var closes=val("vlWClose"); var ts=closes?new Date(closes).getTime():0;
    post("wager","w_action","wager_create",{kind:val("vlWKind"),target_id:val("vlWTid"),description:val("vlWDesc"),sides:sides,closes_at:ts},function(j){
      b.disabled=false;
      if(!j||!j.ok){ err("vlWErr",(j&&j.err)||"Create failed."); return; }
      toast("Wager created: "+j.id); WL=null; load();
    }); };
  var rbs=document.querySelectorAll("[data-wres]");
  for(var i=0;i<rbs.length;i++){ (function(btn){
    btn.onclick=function(){ btn.disabled=true;
      var wid=btn.getAttribute("data-wres");
      var side=val("vlWRes_"+wid);
      if(!side){ err("vlWResErr","Enter the winning side."); btn.disabled=false; return; }
      post("wager","w_action","wager_resolve",{wager_id:wid,winning_side:side},function(j){
        btn.disabled=false;
        if(!j||!j.ok){ err("vlWResErr",(j&&j.err)||"Resolve failed."); return; }
        toast("Wager resolved. "+(j.payouts||[]).length+" payouts."); WL=null; load();
      }); };
  })(rbs[i]); }
  b=document.getElementById("vlSubProc");
  if(b) b.onclick=function(){ b.disabled=true;
    post("sub","s_action","subscription_process",{},function(j){
      b.disabled=false;
      if(!j||!j.ok){ err("vlSubErr",(j&&j.err)||"Process failed."); return; }
      var out=document.getElementById("vlSubOut");
      if(out) out.textContent="Paid "+(j.paid||0)+" subscriptions, skipped "+(j.skipped||0)+".";
      toast("Subscriptions processed.");
    }); };
  var cwb=document.querySelectorAll("[data-cw]");
  for(var c=0;c<cwb.length;c++){ (function(btn){
    btn.onclick=function(){ btn.disabled=true;
      var pid=btn.getAttribute("data-cw");
      post("cause","c_action","cause_withdraw",{pool_id:pid,amount:Number(val("vlCW_"+pid))||0,note:val("vlCWN_"+pid)},function(j){
        btn.disabled=false;
        if(!j||!j.ok){ err("vlCWErr",(j&&j.err)||"Withdraw failed."); return; }
        toast("Disbursed "+(j.withdrawn||0)+" XP from "+pid+"."); CL=null; load();
      }); };
  })(cwb[i]); }
  b=document.getElementById("vlPAward");
  if(b) b.onclick=function(){ b.disabled=true;
    post("prize","p_action","prize_award",{pool_id:val("vlPPool"),winner:val("vlPWin")},function(j){
      b.disabled=false;
      if(!j||!j.ok){ err("vlPErr",(j&&j.err)||"Award failed."); return; }
      toast("Awarded "+(j.amount||0)+" XP to "+j.winner+".");
    }); };
  var eab=document.querySelectorAll("[data-ea]");
  for(var e=0;e<eab.length;e++){ (function(btn){
    btn.onclick=function(){ btn.disabled=true;
      var eid=btn.getAttribute("data-ea");
      var cs=val("vlEA_"+eid);
      if(!cs){ err("vlEAErr","Enter a callsign."); btn.disabled=false; return; }
      post("irl","irl_action","event_attended",{event_id:eid,callsign:cs},function(j){
        btn.disabled=false;
        if(!j||!j.ok){ err("vlEAErr",(j&&j.err)||"Confirm failed."); return; }
        toast(j.dup?"Already confirmed.":"Attendance confirmed. +100 XP to "+cs+".");
      }); };
  })(eab[e]); }
  b=document.getElementById("vlDCreate");
  if(b) b.onclick=function(){ b.disabled=true;
    var at=val("vlDAt"); var ts=at?new Date(at).getTime():0;
    post("drop","d_action","drop_create",{title:val("vlDTitle"),content_id:val("vlDCid"),drop_at:ts},function(j){
      b.disabled=false;
      if(!j||!j.ok){ err("vlDErr",(j&&j.err)||"Create failed."); return; }
      toast("Drop created: "+j.id); DL=null; load();
    }); };
  b=document.getElementById("vlACreate");
  if(b) b.onclick=function(){ b.disabled=true;
    post("alert","al_action","alert_create",{headline:val("vlAHead"),context:val("vlACtx"),template_id:val("vlATpl")},function(j){
      b.disabled=false;
      if(!j||!j.ok){ err("vlAErr",(j&&j.err)||"Create failed."); return; }
      toast("Alert created: "+j.id); AL=null; load();
    }); };
}
renderGate();
setInterval(function(){ if(getSecret()) load(); },300000);
})();
</scr`+`ipt>
</div>
</template>`);
})();

;